function renderPMCodeBlock(app, getClient, source, el) {
  const cfg = parseConfig(source);
  const projects = parseProjects(cfg);
  if (!projects.length) {
    el.createEl("p", {
      text: "nnn-pm: missing `project: <KEY>` (or `projects: ENG, MKT`)",
      cls: "nnn-pm-error"
    });
    return;
  }
  const viewId = (cfg.view || "board").trim().toLowerCase();
  const view = pmViews.get(viewId);
  if (!view) {
    el.createEl("p", {
      text: `nnn-pm: unknown view "${viewId}" \u2014 available: ${pmViews.list().map((v) => v.id).join(", ")}`,
      cls: "nnn-pm-error"
    });
    return;
  }
  const scope = { projects, plane: "pm" };
  void view.render(el, {
    app,
    client: getClient(),
    scope,
    reload: () => renderPMCodeBlock(app, getClient, source, el)
  });
}
function parseProjects(cfg) {
  if (cfg.projects) {
    return cfg.projects.split(",").map((s) => s.trim().toUpperCase()).filter(Boolean);
  }
  if (cfg.project) return [cfg.project.trim().toUpperCase()];
  return [];
}
function parseConfig(source) {
  const out = {};
  for (const line of source.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const idx = trimmed.indexOf(":");
    if (idx < 0) continue;
    const key = trimmed.slice(0, idx).trim().toLowerCase();
    const val = trimmed.slice(idx + 1).trim();
    if (key) out[key] = val;
  }
  return out;
}

